import math

def get_divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def sigma(n):
    # Function to calculate sum of divisors
    sum_div = 0
    for d in get_divisors(n):
        sum_div += d
    return sum_div

def is_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

def solve_backtracking(m, divisors):
    """
    Backtracking search to find a permutation (a1, ..., an) such that 
    partial sums are perfect squares.
    """
    N = len(divisors)
    target_sum = sigma(m)

    # A divisor must be a perfect square divisor if it starts the sequence (a1)
    square_divisors = [d for d in divisors if math.isqrt(d)**2 == d]

    if not square_divisors:
        # Should not happen for m>1, as 1 is always a square divisor
        return None

    # We use a set for efficient tracking of remaining divisors
    divisors_set = set(divisors)

    def backtrack(current_path, current_sum, used_divisors):
        if len(current_path) == N:
            if current_sum == target_sum and is_square(current_sum):
                return current_path
            return None

        # Iterate over all available divisors
        for d in divisors:
            if d not in used_divisors:
                next_sum = current_sum + d

                if is_square(next_sum):
                    # Check if this move is valid and proceed
                    new_path = current_path + [d]
                    new_used = used_divisors | {d}

                    result = backtrack(new_path, next_sum, new_used)
                    if result:
                        return result
        return None

    # The first element a1 must be a perfect square divisor.
    for a1 in square_divisors:
        start_sum = a1
        if is_square(start_sum): # This is guaranteed since a1 is a square
            path = [a1]
            used = {a1}
            result = backtrack(path, start_sum, used)
            if result:
                return result

    return None

